import { MakeLogicType, actions, afterMount, connect, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from '@posthog/lemon-ui'

import { teamLogic } from 'scenes/teamLogic'

import {
    visionAlertsDestroy,
    visionAlertsList,
    visionAlertsPartialUpdate,
    visionAlertsResetCreate,
} from '../generated/api'
import type { PatchedVisionAlertConfigurationApi, VisionAlertConfigurationApi } from '../generated/api.schemas'

export interface ScannerAlertsLogicProps {
    scannerId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scannerAlertsLogicValues {
    currentTeamId: number | null // teamLogic
    alerts: VisionAlertConfigurationApi[]
    alertsLoading: boolean
    busyAlertIds: Set<string>
    editingAlert: VisionAlertConfigurationApi | null
    isCreateAlertModalOpen: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scannerAlertsLogicActions {
    closeCreateAlertModal: () => {
        value: true
    }
    closeEditAlertModal: () => {
        value: true
    }
    deleteAlert: (
        id: string,
        onSuccess?: () => void
    ) => {
        id: string
        onSuccess: (() => void) | undefined
    }
    loadAlerts: (_?: any) => any
    loadAlertsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadAlertsSuccess: (
        alerts: VisionAlertConfigurationApi[],
        payload?: any
    ) => {
        alerts: VisionAlertConfigurationApi[]
        payload?: any
    }
    openCreateAlertModal: () => {
        value: true
    }
    openEditAlertModal: (alert: VisionAlertConfigurationApi) => {
        alert: VisionAlertConfigurationApi
    }
    resetAlert: (id: string) => {
        id: string
    }
    setAlertBusy: (
        id: string,
        busy: boolean
    ) => {
        busy: boolean
        id: string
    }
    snoozeAlertUntil: (
        alertId: string,
        snoozeUntil: string
    ) => {
        alertId: string
        snoozeUntil: string
    }
    toggleAlertEnabled: (alert: VisionAlertConfigurationApi) => {
        alert: VisionAlertConfigurationApi
    }
    unsnoozeAlert: (alertId: string) => {
        alertId: string
    }
    updateEditingAlert: (alert: VisionAlertConfigurationApi) => {
        alert: VisionAlertConfigurationApi
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scannerAlertsLogicMeta {
    key: string
}

export type scannerAlertsLogicType = MakeLogicType<
    scannerAlertsLogicValues,
    scannerAlertsLogicActions,
    ScannerAlertsLogicProps,
    scannerAlertsLogicMeta
>

export const scannerAlertsLogic = kea<scannerAlertsLogicType>([
    path(['products', 'replay_vision', 'frontend', 'replay_scanners', 'scannerAlertsLogic']),
    props({} as ScannerAlertsLogicProps),
    key((props) => props.scannerId),
    connect(() => ({ values: [teamLogic, ['currentTeamId']] })),

    actions({
        deleteAlert: (id: string, onSuccess?: () => void) => ({ id, onSuccess }),
        toggleAlertEnabled: (alert: VisionAlertConfigurationApi) => ({ alert }),
        resetAlert: (id: string) => ({ id }),
        setAlertBusy: (id: string, busy: boolean) => ({ id, busy }),
        snoozeAlertUntil: (alertId: string, snoozeUntil: string) => ({ alertId, snoozeUntil }),
        unsnoozeAlert: (alertId: string) => ({ alertId }),
        openCreateAlertModal: true,
        closeCreateAlertModal: true,
        openEditAlertModal: (alert: VisionAlertConfigurationApi) => ({ alert }),
        closeEditAlertModal: true,
        updateEditingAlert: (alert: VisionAlertConfigurationApi) => ({ alert }),
    }),

    reducers({
        busyAlertIds: [
            new Set<string>(),
            {
                setAlertBusy: (state, { id, busy }) =>
                    busy ? new Set([...state, id]) : new Set([...state].filter((x) => x !== id)),
            },
        ],
        isCreateAlertModalOpen: [
            false,
            {
                openCreateAlertModal: () => true,
                closeCreateAlertModal: () => false,
            },
        ],
        editingAlert: [
            null as VisionAlertConfigurationApi | null,
            {
                openEditAlertModal: (_, { alert }) => alert,
                closeEditAlertModal: () => null,
                updateEditingAlert: (editingAlert, { alert }) => (editingAlert?.id === alert.id ? alert : editingAlert),
            },
        ],
    }),

    loaders(({ props, values }) => ({
        alerts: [
            [] as VisionAlertConfigurationApi[],
            {
                loadAlerts: async (_?: any, breakpoint?: any) => {
                    const response = await visionAlertsList(String(values.currentTeamId), {
                        scanner_id: props.scannerId,
                    })
                    breakpoint?.()
                    return response.results
                },
            },
        ],
    })),

    listeners(({ actions, values }) => ({
        deleteAlert: async ({ id, onSuccess }) => {
            try {
                await visionAlertsDestroy(String(values.currentTeamId), id)
                lemonToast.success('Alert deleted')
                actions.loadAlerts()
                onSuccess?.()
            } catch {
                lemonToast.error('Could not delete the alert. Try again.')
            }
        },
        toggleAlertEnabled: async ({ alert }) => {
            const update: PatchedVisionAlertConfigurationApi = { enabled: !(alert.enabled ?? true) }
            if (!update.enabled) {
                update.snooze_until = null
            }
            actions.setAlertBusy(alert.id, true)
            try {
                const updated = await visionAlertsPartialUpdate(String(values.currentTeamId), alert.id, update)
                actions.updateEditingAlert(updated)
                actions.loadAlerts()
            } catch {
                lemonToast.error('Could not update the alert. Try again.')
            } finally {
                actions.setAlertBusy(alert.id, false)
            }
        },
        resetAlert: async ({ id }) => {
            actions.setAlertBusy(id, true)
            try {
                await visionAlertsResetCreate(String(values.currentTeamId), id)
                lemonToast.success('Alert reset. The next check runs shortly.')
                actions.loadAlerts()
            } catch {
                lemonToast.error('Could not reset the alert. Try again.')
            } finally {
                actions.setAlertBusy(id, false)
            }
        },
        snoozeAlertUntil: async ({ alertId, snoozeUntil }) => {
            actions.setAlertBusy(alertId, true)
            try {
                const updated = await visionAlertsPartialUpdate(String(values.currentTeamId), alertId, {
                    snooze_until: snoozeUntil,
                })
                actions.updateEditingAlert(updated)
                lemonToast.success('Alert snoozed')
                actions.loadAlerts()
            } catch {
                lemonToast.error('Could not snooze the alert. Try again.')
            } finally {
                actions.setAlertBusy(alertId, false)
            }
        },
        unsnoozeAlert: async ({ alertId }) => {
            actions.setAlertBusy(alertId, true)
            try {
                const updated = await visionAlertsPartialUpdate(String(values.currentTeamId), alertId, {
                    snooze_until: null,
                })
                actions.updateEditingAlert(updated)
                lemonToast.success('Alert unsnoozed')
                actions.loadAlerts()
            } catch {
                lemonToast.error('Could not unsnooze the alert. Try again.')
            } finally {
                actions.setAlertBusy(alertId, false)
            }
        },
    })),

    afterMount(({ actions }) => {
        actions.loadAlerts()
    }),
])
